      clubContractAction(probe,p.id,'renew'):{ok:false,msg:p.loan?'임대 계약과 원소속 재계약은 별도로 처리합니다':c?.medicalReplacement?'의료 대체 계약의 일별 종료는 별도 조건입니다':'현재 수동 계약 권한이 없습니다'};
    let option=null;
